def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def step_toward(a, b):
        return clamp_step(b - a)

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def first_pos(obs, keys, default=(0, 0)):
        for k in keys:
            v = obs.get(k)
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return (v[0], v[1])
        return default

    def safe_int(x, default=0):
        try:
            return int(x)
        except Exception:
            return default

    def get_grid_dims(obs):
        w = safe_int(obs.get("grid_width", obs.get("width", 0)), 0)
        h = safe_int(obs.get("grid_height", obs.get("height", 0)), 0)
        if w <= 0:
            w = 1
        if h <= 0:
            h = 1
        return w, h

    env = observation.get("environment_name", "resource_collection")
    sx, sy = first_pos(observation, ("self_position", "position", "agent_position"), (0, 0))
    ox, oy = first_pos(observation, ("opponent_position", "enemy_position", "other_position"), (sx, sy))
    w, h = get_grid_dims(observation)
    cx, cy = w // 2, h // 2

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = max(corners, key=lambda p: manhattan(p, (ox, oy)) + manhattan(p, (sx, sy)) * 0.1)
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("neutral_cells")
        if targets:
            best = min(targets, key=lambda p: manhattan((sx, sy), (p[0], p[1])))
            return [step_toward(sx, best[0]), step_toward(sy, best[1])]
        return [step_toward(sx, cx), step_toward(sy, cy)]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    if resources:
        best = min(resources, key=lambda p: manhattan((sx, sy), (p[0], p[1])))
        return [step_toward(sx, best[0]), step_toward(sy, best[1])]

    if manhattan((sx, sy), (ox, oy)) <= 2:
        dx = clamp_step(sx - ox)
        dy = clamp_step(sy - oy)
        if dx == 0 and dy == 0:
            dx = 1 if sx < w - 1 else -1 if sx > 0 else 0
            dy = 1 if sy < h - 1 else -1 if sy > 0 else 0
        return [dx, dy]

    return [step_toward(sx, cx), step_toward(sy, cy)]

